import path from "node:path"
import { Database } from "bun:sqlite"
import { eq, sql } from "drizzle-orm"
import { drizzle } from "drizzle-orm/bun-sqlite"
import { readMigrationFiles } from "drizzle-orm/migrator"
import { migrate } from "drizzle-orm/bun-sqlite/migrator"
import { env } from "../config/env.ts"
import * as schema from "./schema/index.ts"

/** Folder of SQL migrations generated by `bun run db:generate`. */
const MIGRATIONS_FOLDER = path.join(import.meta.dir, "../../drizzle")

/** Raw SQLite handle for app data (WAL mode, foreign keys on). Use {@link db}. */
const sqlite = new Database(path.join(env.DATA_DIR, "app.db"))
sqlite.exec(
	`PRAGMA journal_mode = WAL;
   PRAGMA synchronous = NORMAL;
   PRAGMA foreign_keys = ON;
   PRAGMA busy_timeout = 5000;`
)

/** Drizzle client over {@link sqlite}, typed with every table in the schema. */
export const db = drizzle(sqlite, { schema })

/**
 * Databases created before Drizzle already contain every baseline table but no migrations journal.
 * Records the baseline migration as applied for those, so it is not run against existing tables.
 */
function baselineExistingDatabase() {
	const hasTable = (tableName: string) =>
		sqlite
			.query(
				`SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?`
			)
			.get(tableName) !== null
	if (hasTable("__drizzle_migrations") || !hasTable("bank_connection")) {
		return
	}
	const [baseline] = readMigrationFiles({
		migrationsFolder: MIGRATIONS_FOLDER,
	})
	sqlite.exec(`CREATE TABLE "__drizzle_migrations" (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		hash TEXT NOT NULL,
		created_at NUMERIC
	)`)
	sqlite
		.query(
			`INSERT INTO "__drizzle_migrations" (hash, created_at) VALUES (?, ?)`
		)
		.run(baseline.hash, baseline.folderMillis)
}

/** Applies any pending schema migrations (adopting a pre-Drizzle database first). Call once at startup. */
export function runMigrations() {
	baselineExistingDatabase()
	migrate(db, { migrationsFolder: MIGRATIONS_FOLDER })
}

/** Reads a string value from the settings table, or null when unset. */
export function getSetting(key: string): string | null {
	const row = db
		.select({ value: schema.appSetting.value })
		.from(schema.appSetting)
		.where(eq(schema.appSetting.key, key))
		.get()
	return row?.value ?? null
}

/** Writes a string value to the settings table, replacing any existing one. */
export function setSetting(key: string, value: string) {
	db.insert(schema.appSetting)
		.values({ key, value })
		.onConflictDoUpdate({
			target: schema.appSetting.key,
			set: { value: sql`excluded.value` },
		})
		.run()
}
